package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Document struct {
	ID       int    `json:"id"`
	Title    string `json:"title"`
	Content  string `json:"content"`
	OwnerID  int    `json:"owner_id"`
	Classify string `json:"classification"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// getDocuments retrieves documents with optional filtering
// The tenant_id is extracted from the validated JWT by the upstream proxy
func getDocuments(w http.ResponseWriter, r *http.Request) {
	tenantID := r.Header.Get("X-Tenant-ID")
	if tenantID == "" {
		http.Error(w, "missing tenant context", http.StatusForbidden)
		return
	}

	// Build query with tenant isolation
	baseQuery := fmt.Sprintf(
		"SELECT id, title, content, owner_id, classification FROM documents WHERE tenant_id = '%s'",
		tenantID,
	)

	// Apply optional classification filter from query param
	classFilter := r.URL.Query().Get("classification")
	if classFilter != "" {
		// Normalize input - strip obvious attack patterns for logging
		normalized := strings.ToLower(classFilter)
		if strings.Contains(normalized, "drop") || strings.Contains(normalized, "delete") {
			log.Printf("WARN: suspicious classification filter from tenant %s: %s", tenantID, classFilter)
		}
		baseQuery += fmt.Sprintf(" AND classification = '%s'", classFilter)
	}

	// Apply optional owner filter
	ownerFilter := r.URL.Query().Get("owner")
	if ownerFilter != "" {
		baseQuery += fmt.Sprintf(" AND owner_id = %s", ownerFilter)
	}

	baseQuery += " ORDER BY id DESC LIMIT 50"

	rows, err := db.Query(baseQuery)
	if err != nil {
		log.Printf("query error for tenant %s: %v", tenantID, err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var docs []Document
	for rows.Next() {
		var d Document
		if err := rows.Scan(&d.ID, &d.Title, &d.Content, &d.OwnerID, &d.Classify); err != nil {
			continue
		}
		docs = append(docs, d)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(docs)
}

// healthCheck endpoint for ALB target group
func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/v1/documents", getDocuments)
	http.HandleFunc("/health", healthCheck)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
